<?php
declare(strict_types=1);
function prod_detail(int $id):array{
 $r=prod_run($id);$p=prod_plan((int)$r['plan_id']);$r['plan']=$p;$r['steps']=crm_query('SELECT * FROM nd_prod_steps WHERE run_id=? ORDER BY id',[$id])->fetchAll();$r['artifacts']=crm_query('SELECT a.*,s.step_key FROM nd_prod_artifacts a JOIN nd_prod_steps s ON s.id=a.step_id WHERE s.run_id=? ORDER BY a.id',[$id])->fetchAll();$r['qa']=crm_query('SELECT * FROM nd_prod_qa_reports WHERE run_id=? ORDER BY id DESC',[$id])->fetchAll();$r['findings']=crm_query('SELECT f.* FROM nd_prod_findings f JOIN nd_prod_qa_reports q ON q.id=f.report_id WHERE q.run_id=? ORDER BY f.id DESC LIMIT 100',[$id])->fetchAll();$r['packages']=crm_query('SELECT * FROM nd_prod_packages WHERE run_id=? ORDER BY id DESC',[$id])->fetchAll();$r['events']=crm_query('SELECT category,created_at FROM nd_prod_events WHERE run_id=? ORDER BY id',[$id])->fetchAll();$r['revisions']=crm_query('SELECT * FROM nd_prod_revisions WHERE run_id=? ORDER BY cycle',[$id])->fetchAll();$r['costs']=prod_cost_report($id);return ['ok'=>true,'record'=>$r];
}
function prod_customer(array $a,int $project):array{
 cc_project($a,$project);$r=crm_query('SELECT r.id,r.state FROM nd_prod_runs r JOIN nd_prod_plans p ON p.id=r.plan_id WHERE p.project_id=? ORDER BY r.id DESC LIMIT 1',[$project])->fetch();$map=['EXECUTING'=>'Выполнение работ','PAUSED'=>'Ожидает решения специалиста','NEEDS_HUMAN'=>'Ожидает решения специалиста','QA_REJECTED'=>'Проверка и доработка','READY'=>'Результат на проверке у исполнителя','DELIVERED'=>'Ожидает вашего согласования','COMPLETED'=>'Завершено','CANCELLED'=>'Работы остановлены'];return ['ok'=>true,'project_id'=>$project,'status'=>$r?($map[$r['state']]??'Подготовка проекта'):'Подготовка проекта','delivered'=>$r&&in_array($r['state'],['DELIVERED','COMPLETED'],true),'deliverables_url'=>'/collaboration.php?project='.$project.'#deliverables'];
}
